<?php
/** @var string $base @var string $csrf @var array $tenant @var array $invoices @var array $proofsByInvoice @var array $summary @var array $legacyPayments @var bool $invoiceSchemaAvailable */
$e = static fn($value): string => htmlspecialchars((string) $value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
$money = static fn($value): string => 'Rp' . number_format((float)$value, 0, ',', '.');
$labels = ['unpaid'=>'Belum lunas','paid'=>'Lunas','overdue'=>'Terlambat','void'=>'Dibatalkan'];
$tones = ['unpaid'=>'warning','paid'=>'success','overdue'=>'danger','void'=>'secondary'];
?>
<div class="alert alert-info py-2">Invoice dapat dibuat manual atau otomatis menjelang akhir masa aktif. Transfer bank dan upload bukti belum mengaktifkan langganan sampai Admin memverifikasi pembayaran.</div>
<div class="row g-2 mb-3">
  <div class="col-md-4"><div class="metric-card"><div class="metric-label">Paket akun</div><div class="metric-value fs-5 mt-2"><?= $e($tenant['plan_name']) ?></div><div class="small text-muted"><?= (float)$tenant['price_monthly'] === 0.0 ? 'Gratis' : $money($tenant['price_monthly']) . ' / bulan' ?></div></div></div>
  <div class="col-md-4"><div class="metric-card"><div class="metric-label">Status</div><div class="metric-value fs-5 mt-2"><?= $e($tenant['status']) ?></div><div class="small text-muted">Berlaku sampai <?= $e($tenant['subscription_ends_at'] ? date('d M Y',strtotime((string)$tenant['subscription_ends_at'])) : 'tanpa batas waktu') ?></div></div></div>
  <div class="col-md-4"><div class="metric-card"><div class="metric-label">Tagihan belum lunas</div><div class="metric-value fs-5 mt-2"><?= $money($summary['outstanding'] ?? 0) ?></div><div class="small text-muted"><?= number_format((int)($summary['overdue_count'] ?? 0),0,',','.') ?> terlambat · <?= number_format((int)($summary['unpaid_count'] ?? 0),0,',','.') ?> belum jatuh tempo</div></div></div>
</div>
<div class="card mb-3">
  <div class="card-header d-flex justify-content-between align-items-center"><div><strong>Invoice langganan</strong><div class="small text-muted">Invoice ini berlaku bersama untuk seluruh usaha pada akun Anda.</div></div><span class="badge text-bg-light border"><?= count($invoices) ?> ditampilkan</span></div>
  <div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Invoice</th><th>Usaha</th><th>Periode layanan</th><th>Jatuh tempo</th><th>Nominal</th><th>Status</th><th>Pembayaran</th><th>Bukti transfer</th></tr></thead><tbody>
    <?php foreach ($invoices as $invoice): $status=$invoice['display_status']; ?>
      <?php $proof = $proofsByInvoice[(int)$invoice['id']] ?? null; ?>
      <tr><td><a class="fw-semibold text-decoration-none" href="<?= $e($base) ?>/owner/billing/invoice?id=<?= (int)$invoice['id'] ?>"><?= $e($invoice['invoice_no']) ?></a><div class="small text-muted">Terbit <?= $e($invoice['issued_at']) ?></div></td>
        <td><?= $e($invoice['tenant_name']) ?></td><td class="text-nowrap"><?= $e($invoice['period_start']) ?><div class="small text-muted">s.d. <?= $e($invoice['period_end']) ?></div></td>
        <td class="text-nowrap"><?= $e($invoice['due_at']) ?><div class="small text-muted">Tenggang s.d. <?= $e($invoice['grace_until']) ?></div></td><td class="fw-semibold text-nowrap"><?= $money($invoice['amount']) ?></td>
        <td><span class="badge text-bg-<?= $e($tones[$status] ?? 'secondary') ?>"><?= $e($labels[$status] ?? $status) ?></span></td><td class="small"><?= $invoice['paid_at'] ? $e($invoice['paid_at']) . '<div class="text-muted">' . $e($invoice['payment_method']) . ' · ' . $e($invoice['reference']) . '</div>' : 'Menunggu konfirmasi Admin' ?></td>
        <td><?php if ($status === 'paid'): ?><span class="small text-success">Terverifikasi</span><?php elseif ($proof && $proof['status'] === 'pending'): ?><span class="badge text-bg-warning">Menunggu verifikasi</span><a class="d-block small mt-1" href="<?= $e($base) ?>/owner/billing/proof/file?id=<?= (int)$proof['id'] ?>">Lihat bukti</a><?php else: ?>
          <?php if ($proof && $proof['status'] === 'rejected'): ?><div class="small text-danger mb-1">Ditolak: <?= $e($proof['reviewer_note'] ?: 'silakan kirim bukti yang valid') ?></div><?php endif; ?>
          <details><summary class="btn btn-outline-primary btn-sm">Upload bukti</summary><form method="post" action="<?= $e($base) ?>/owner/billing/proof/submit" enctype="multipart/form-data" class="package-edit mt-2"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="invoice_id" value="<?= (int)$invoice['id'] ?>"><label class="form-label small" for="paidAt<?= (int)$invoice['id'] ?>">Tanggal transfer</label><input class="form-control form-control-sm mb-2" id="paidAt<?= (int)$invoice['id'] ?>" name="paid_at" type="date" max="<?= date('Y-m-d') ?>" value="<?= date('Y-m-d') ?>" required><label class="form-label small" for="method<?= (int)$invoice['id'] ?>">Metode</label><select class="form-select form-select-sm mb-2" id="method<?= (int)$invoice['id'] ?>" name="payment_method"><option value="bank_transfer">Transfer bank</option><option value="qris">QRIS</option><option value="other">Lainnya</option></select><label class="form-label small" for="reference<?= (int)$invoice['id'] ?>">Nomor referensi transfer</label><input class="form-control form-control-sm mb-2" id="reference<?= (int)$invoice['id'] ?>" name="reference" maxlength="120" required><label class="form-label small" for="proofFile<?= (int)$invoice['id'] ?>">File bukti (PDF/JPG/PNG, maks. 5 MB)</label><input class="form-control form-control-sm mb-2" id="proofFile<?= (int)$invoice['id'] ?>" name="proof" type="file" accept="application/pdf,image/jpeg,image/png" required><button class="btn btn-primary btn-sm" type="submit">Kirim untuk verifikasi</button></form></details>
        <?php endif; ?></td>
      </tr>
    <?php endforeach; ?>
    <?php if (!$invoices): ?><tr><td colspan="8" class="text-center text-muted py-4"><?= $invoiceSchemaAvailable ? 'Belum ada invoice untuk akun ini.' : 'Invoice belum tersedia. Hubungi administrator jika Anda memerlukan tagihan.' ?></td></tr><?php endif; ?>
  </tbody></table></div>
  <?php if ($invoices): ?><div class="card-footer small text-muted">Invoice yang terlambat mendapat masa tenggang 7 hari. Status billing tidak mengubah akses usaha secara otomatis.</div><?php endif; ?>
</div>
<?php if ($legacyPayments): ?><details class="card"><summary class="card-header package-summary fw-semibold">Riwayat pembayaran lama</summary><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Tanggal</th><th>Usaha</th><th>Periode</th><th>Nominal</th><th>Referensi</th></tr></thead><tbody><?php foreach ($legacyPayments as $payment): ?><tr><td><?= $e($payment['paid_at']) ?></td><td><?= $e($payment['tenant_name']) ?></td><td><?= $e($payment['period_start']) ?> – <?= $e($payment['period_end']) ?></td><td><?= $money($payment['amount']) ?></td><td><?= $e($payment['reference'] ?: '-') ?></td></tr><?php endforeach; ?></tbody></table></div></details><?php endif; ?>